head.script:
scwin.trigger1_onclick = function(e) {
    var id = "addTAB" + i;
    var tabOptions = {
        label: "addTab",
        addTabIndex: 0
    };
    var contentsOptions = {
        frameMode: "iframe",
        src: WebSquare.net.getBlankXML()
    };
    tabControl1.addTab(id, tabOptions, contentsOptions);
    i++;
};
scwin.imageExists = function(image_url) {
    var http = new XMLHttpRequest();
    http.open('HEAD', image_url, false);
    http.send();
    return http.status != 404;
}
scwin.getBaseUrl = function() {
    var currentUrl = window.location.href;
    return currentUrl.split("websquare/")[0] + "/websquare/uiplugin/tabControl/images/tab02_off.gif";
}
scwin.setVal1 = function() {
    //localStorage.setItem('isRefresh', true);
}
scwin.setVal2 = function() {
    //location.reload(true);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 0. IE는 IE11에서만 확인
    //0. IE only checked in IE11
    //Verify step 0. IE10,9,8,7,6은 제외
    //0. Excluding IE10,9,8,7 and 6
    //Test step 1. 샘플파일 실행 후 개발자모드 > network > img를 클릭 하고 실행화면의 addTAB버튼을 클릭한다.
    //1. After executing the sample file, click the developer mode> network> img and click the addTAB button in the execution screen.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. 개발자모드의 네트워크환경이 보여진다.
    //1. The network environment of developer mode is shown.
    //Test step 2. 새로고침(F5)수행 후 개발자도구(img)에 있는 tab02_off.gif파일명을 클릭하여 Request Url을 확인한다.
    //2. After refreshing (F5), check the request URL by clicking the tab02_off.gif file name in the developer"s tool (img).
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "localStorage.clear();");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.i = 0;
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 03-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
